INSERT INTO `destinations` (`id`, `category_id`, `name`, `name_en`, `slug`, `short_desc`, `short_desc_en`, `description`, `description_en`, `address`, `province`, `region`, `opening_hours`, `entrance_fee_min`, `entrance_fee_max`, `contact_phone`, `source_url`, `last_verified_at`, `image_url`, `is_featured`, `image_360_url`, `avg_visit_hours`, `price_level`, `rating`, `latitude`, `longitude`, `virtual_tour_enabled`, `virtual_tour_type`, `audio_guide_url`, `tags`, `created_at`, `updated_at`, `place_id`, `indoor_type`, `weather_sensitivity`) VALUES
(1, 2, 'Hồ Lắk', 'Lak Lake', 'ho-lak', 'Hồ nước ngọt tự nhiên lớn thứ 2 Việt Nam, gắn với văn hoá M\'nông.', 'The 2nd largest natural freshwater lake in Vietnam, deeply connected to M\'nong culture.', 'Hồ Lắk là một trong những hồ nước ngọt tự nhiên lớn nhất Việt Nam, nằm tại huyện Lắk, tỉnh Đắk Lắk. Du khách có thể đi thuyền độc mộc, cưỡi voi, tham quan Biệt điện Bảo Đại và trải nghiệm văn hoá người M\'nông quanh hồ.', 'Lak Lake is a famous eco-tourism destination in Dak Lak. Visitors can experience dugout canoe rides, admire the sunset on the lake, and explore the traditional longhouses of the M\'nong people.', 'Huyện Lắk, Đắk Lắk', NULL, 'west', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_1.jpg', 1, '/assets/images/360/lake.png', 3.0, 'low', 5.0, 12.420300, 108.185400, 1, 'pannellum', NULL, 'thiên nhiên,hồ,văn hoá,thuyền độc mộc', '2026-06-28 05:57:43', '2026-08-06 11:40:02', NULL, 'outdoor', 3),
(2, 1, 'Thác Dray Nur', 'Dray Nur Waterfall', 'thac-dray-nur', 'Một trong những thác nước hùng vĩ nhất Tây Nguyên.', 'One of the most majestic waterfalls in the Central Highlands.', 'Thác Dray Nur nằm trên dòng sông Sêrêpốk, là một trong những thác nước đẹp và hùng vĩ nhất khu vực Tây Nguyên, thích hợp cho trekking, chụp ảnh và tắm thác.', 'Dray Nur waterfall is breathtakingly beautiful with its massive curtain of water. You can explore the mysterious cave behind the waterfall and enjoy the pristine nature.', 'Huyện Krông Ana, Đắk Lắk', NULL, 'west', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_2.jpg', 1, '/assets/images/360/waterfall.png', 2.5, 'low', 5.0, 12.566700, 108.116700, 1, 'pannellum', NULL, 'thiên nhiên,thác nước,trekking', '2026-06-28 05:57:43', '2026-08-06 11:40:02', NULL, 'outdoor', 3),
(3, 1, 'Thác Dray Sáp', 'Dray Sap Waterfall', 'thac-dray-sap', 'Thác \"nước khói\" nổi tiếng gần Buôn Ma Thuột.', 'The famous \'smoke waterfall\' near Buon Ma Thuot.', 'Thác Dray Sáp (nghĩa là \"thác khói\") nổi tiếng với dòng nước tung bọt trắng như sương khói, gần khu vực Dray Nur, thuận tiện kết hợp tham quan trong cùng ngày.', 'Located near Dray Nur, Dray Sap is known for the mist that rises from the falling water, creating a mystical atmosphere in the middle of the jungle.', 'Huyện Krông Ana, Đắk Lắk', NULL, 'west', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_3.jpg', 1, '/assets/images/360/draysap.png', 2.0, 'low', 4.5, 12.572800, 108.108300, 1, 'pannellum', NULL, 'thiên nhiên,thác nước', '2026-06-28 05:57:43', '2026-08-06 11:40:02', NULL, 'outdoor', 3),
(4, 3, 'Buôn Đôn', 'Buon Don', 'buon-don', 'Làng văn hoá nổi tiếng với nghề săn bắt và thuần dưỡng voi.', 'Famous for its elephant taming tradition and the suspension bridge over Serepok river.', 'Buôn Đôn là điểm đến văn hoá nổi tiếng của Đắk Lắk, nơi du khách tìm hiểu về nghề thuần dưỡng voi, tham quan nhà dài truyền thống, cầu treo và mộ vua voi Khunjunob.', 'Experience the wild nature, walk on the long suspension bridge, and learn about the unique culture of the local ethnic minorities.', 'Huyện Buôn Đôn, Đắk Lắk', NULL, 'west', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_4.jpg', 1, '/assets/images/360/buondon.png', 3.0, 'medium', 4.4, 13.016700, 107.833300, 1, 'pannellum', NULL, 'văn hoá,voi,nhà dài,cầu treo', '2026-06-28 05:57:43', '2026-08-06 11:40:02', NULL, 'indoor', 0),
(5, 4, 'Vườn quốc gia Yok Đôn', 'Yok Don National Park', 'vuon-quoc-gia-yok-don', 'Vườn quốc gia lớn nhất Việt Nam, nơi sinh sống của voi rừng.', 'The only national park in Vietnam that preserves the dipterocarp forest ecosystem.', 'Yok Đôn là vườn quốc gia lớn nhất Việt Nam, nổi bật với hệ sinh thái rừng khô đặc trưng Tây Nguyên và là nơi triển khai mô hình du lịch thân thiện với voi (không cưỡi voi).', 'A paradise for nature lovers. You can join trekking tours, go bird watching, and see the ethical elephant tours where elephants roam freely.', 'Huyện Buôn Đôn, Đắk Lắk', NULL, 'west', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_5.jpg', 1, '/assets/images/360/yokdon.png', 4.0, 'medium', 4.5, 13.083300, 107.783300, 1, 'pannellum', NULL, 'thiên nhiên,rừng,voi,sinh thái', '2026-06-28 05:57:43', '2026-08-06 11:40:02', NULL, 'outdoor', 3),
(6, 5, 'Cà phê Buôn Ma Thuột', 'Buon Ma Thuot Coffee', 'ca-phe-buon-ma-thuot', 'Thủ phủ cà phê Việt Nam, trải nghiệm văn hoá cà phê đặc sắc.', 'The coffee capital of Vietnam, a great place to experience the culture of roasted coffee.', 'Buôn Ma Thuột được mệnh danh là \"thủ phủ cà phê\" của Việt Nam. Du khách có thể tham quan các đồn điền cà phê, Bảo tàng Thế giới Cà phê và thưởng thức cà phê nguyên chất Đắk Lắk.', 'A must-visit for coffee lovers. You can learn about the history of coffee, admire unique architecture, and taste premium coffee blends.', 'TP. Buôn Ma Thuột, Đắk Lắk', NULL, 'west', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_6.jpg', 1, '/assets/images/360/coffee.png', 2.0, 'free', 0.0, 12.666700, 108.050000, 1, 'pannellum', NULL, 'ẩm thực,cà phê,bảo tàng', '2026-06-28 05:57:43', '2026-08-06 11:40:02', NULL, 'indoor', 0),
(7, 3, 'Buôn Akô Dhông', 'Ako Dhong Village', 'buon-ako-dhong', 'Buôn làng Ê Đê đẹp nhất Buôn Ma Thuột.', 'A peaceful E De village in the heart of Buon Ma Thuot city.', 'Buôn Akô Dhông nằm ngay trong lòng thành phố Buôn Ma Thuột, nổi tiếng với những ngôi nhà dài truyền thống của người Ê Đê và không gian xanh yên bình.', 'Ako Dhong is known for its beautiful traditional longhouses, peaceful atmosphere, and the rich cultural heritage of the E De people.', 'TP. Buôn Ma Thuột, Đắk Lắk', NULL, 'west', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_7.jpg', 1, '/assets/images/360/akodhong.png', 1.5, 'free', 4.3, 12.683300, 108.033300, 1, 'pannellum', NULL, 'văn hoá,nhà dài,Ê Đê', '2026-06-28 05:57:43', '2026-08-06 11:40:02', NULL, 'indoor', 0),
(8, 2, 'Hồ Ea Kao', 'Ea Kao Lake', 'ho-ea-kao', 'Hồ nước rộng lớn gần trung tâm thành phố, thích hợp cắm trại.', 'A serene lake surrounded by green forests, perfect for picnics and sunset watching.', 'Hồ Ea Kao là hồ nhân tạo rộng lớn nằm gần TP. Buôn Ma Thuột, không khí mát mẻ, phù hợp cho dã ngoại, cắm trại và chụp ảnh.', 'Ea Kao Lake is a great place to relax, enjoy the fresh air, and watch the beautiful sunset over the water.', 'TP. Buôn Ma Thuột, Đắk Lắk', NULL, 'west', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_8.jpg', 1, '/assets/images/360/eakao.png', 2.0, 'free', 4.2, 12.616700, 108.083300, 1, 'pannellum', NULL, 'thiên nhiên,hồ,cắm trại', '2026-06-28 05:57:43', '2026-08-06 11:40:02', NULL, 'outdoor', 3),
(9, 1, 'Gành Đá Đĩa - Phú Yên', 'Ganh Da Dia - Phu Yen', 'ganh-da-dia-phu-yen', 'Kiệt tác thiên nhiên với các khối đá hình lăng trụ xếp liền nhau.', 'A natural masterpiece with interlocking basalt columns.', 'Gành Đá Đĩa là một trong những danh thắng quốc gia đặc biệt của Phú Yên, thu hút đông đảo du khách bởi cấu tạo địa chất độc đáo. Các khối đá bazan hình lục giác, ngũ giác xếp chồng lên nhau như những chồng đĩa vươn ra biển.', 'Ganh Da Dia is a unique geological phenomenon in Vietnam. It looks like a giant black honeycomb rising from the sea, a must-visit destination in Phu Yen.', NULL, 'Phú Yên', 'east', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_9.jpg', 1, NULL, 3.0, 'low', 4.5, 13.344400, 109.297500, 1, 'pannellum', NULL, 'biển, thiên nhiên, phú yên, chụp ảnh', '2026-07-16 05:31:25', '2026-08-06 11:40:02', NULL, 'outdoor', 3),
(10, 3, 'Đầm Ô Loan', 'O Loan Lagoon', 'dam-o-loan-phu-yen', 'Đầm nước lợ nổi tiếng với đặc sản sò huyết ngon nức tiếng.', 'A brackish lagoon famous for its delicious blood cockles.', 'Nằm yên bình dưới chân đèo Quán Cau, Đầm Ô Loan mang vẻ đẹp tĩnh lặng, thơ mộng. Nơi đây là điểm đến lý tưởng để ngắm hoàng hôn và thưởng thức hải sản tươi sống, đặc biệt là sò huyết.', 'O Loan Lagoon offers a peaceful scenery, especially at sunrise or sunset. Don\'t forget to try the famous seafood here, especially the blood cockles.', NULL, 'Phú Yên', 'east', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_10.jpg', 1, NULL, 2.0, 'medium', 4.5, 13.279200, 109.255800, 1, 'pannellum', NULL, 'hải sản, thiên nhiên, phú yên, ẩm thực', '2026-07-16 05:31:25', '2026-08-06 11:40:02', NULL, 'mixed', 1),
(11, 1, 'Vịnh Vũng Rô', 'Vung Ro Bay', 'vinh-vung-ro', 'Vịnh biển xanh biếc, lịch sử hào hùng và hải sản phong phú.', 'A blue bay with a heroic history and abundant seafood.', 'Vũng Rô là một vịnh nhỏ thuộc xã Hòa Xuân Nam, huyện Đông Hòa. Nơi đây từng là bến đỗ của những con tàu Không số trong chiến tranh. Ngày nay, Vũng Rô níu chân du khách bởi làn nước trong xanh và các bè hải sản tươi ngon.', 'Vung Ro Bay is surrounded by high mountains. It was an important site for the Ho Chi Minh trail on the sea during the war, and now a beautiful spot for tourists.', NULL, 'Phú Yên', 'east', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_11.jpg', 1, NULL, 4.0, 'medium', 4.5, 12.871400, 109.390800, 1, 'pannellum', NULL, 'biển, lịch sử, phú yên, hải sản', '2026-07-16 05:31:25', '2026-08-06 11:40:02', NULL, 'outdoor', 3),
(12, 1, 'Bãi Môn - Mũi Điện', 'Bai Mon - Mui Dien', 'bai-mon-mui-dien', 'Nơi đón bình minh đầu tiên trên đất liền Việt Nam.', 'The easternmost point of Vietnam, welcoming the first sunrise.', 'Mũi Điện (Mũi Đại Lãnh) và Bãi Môn tạo nên một bức tranh tuyệt đẹp. Dưới chân ngọn hải đăng là bãi cát trắng mịn và làn nước trong vắt. Trải nghiệm cắm trại và đón những tia nắng đầu tiên là không thể bỏ lỡ.', 'Mui Dien Cape features a historic lighthouse and the beautiful, pristine Bai Mon beach. It is one of the places to catch the first rays of the sun in Vietnam.', NULL, 'Phú Yên', 'east', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_12.jpg', 1, NULL, 3.0, 'low', 4.5, 12.877200, 109.431900, 1, 'pannellum', NULL, 'biển, bình minh, thiên nhiên, phú yên', '2026-07-16 05:31:25', '2026-08-06 11:40:02', NULL, 'outdoor', 3),
(13, 2, 'Tháp Nghinh Phong', 'Nghinh Phong Tower', 'thap-nghinh-phong', 'Biểu tượng du lịch mới của thành phố Tuy Hòa, Phú Yên.', 'The new tourism symbol of Tuy Hoa city, Phu Yen.', 'Tháp Nghinh Phong được thiết kế lấy cảm hứng từ truyền thuyết Lạc Long Quân - Âu Cơ, mang kiến trúc độc đáo, là điểm check-in không thể bỏ qua khi đến Phú Yên.', 'Inspired by the legend of Lac Long Quan and Au Co, Nghinh Phong Tower features unique architecture and is a must-visit check-in spot when visiting Phu Yen.', 'Tuy Hòa, Phú Yên', 'Phú Yên', 'east', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_13.jpg', 1, NULL, 1.5, 'free', 4.5, 13.084700, 109.324500, 1, 'pannellum', NULL, '', '2026-07-16 06:06:49', '2026-08-06 11:40:02', NULL, 'mixed', 1),
(14, 1, 'Hòn Yến', 'Hon Yen', 'hon-yen-phu-yen', 'Hòn đảo nhỏ với rạn san hô tuyệt đẹp lộ trên mặt nước lúc thủy triều rút.', 'A small island with beautiful coral reefs exposed at low tide.', 'Hòn Yến mang vẻ đẹp hoang sơ. Vào những ngày đầu hoặc giữa tháng âm lịch, khi thủy triều rút xuống, nơi đây để lộ ra những rạn san hô nhiều màu sắc vô cùng rực rỡ.', 'Hon Yen retains its pristine beauty. During the beginning or middle of the lunar month, the low tide reveals incredibly vibrant coral reefs.', 'Tuy An, Phú Yên', NULL, 'east', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_14.jpg', 0, NULL, 2.5, 'low', 4.5, 13.238400, 109.305600, 1, 'pannellum', NULL, '', '2026-07-16 06:06:49', '2026-08-06 11:40:02', NULL, 'mixed', 1),
(15, 1, 'Thác Thủy Tiên', 'Thuy Tien Waterfall', 'thac-thuy-tien-dak-lak', 'Tuyệt tác thiên nhiên ba tầng giữa chốn đại ngàn Krông Năng.', 'A natural masterpiece with three levels in Krong Nang forest.', 'Thác Thủy Tiên (hay còn gọi là thác Ba Tầng) có không gian rộng lớn, hoang sơ và mát mẻ, phù hợp cho các chuyến dã ngoại, tắm suối và khám phá rừng núi.', 'Thuy Tien Waterfall (also known as Three-Level Waterfall) has a spacious, pristine, and cool environment, perfect for picnics, stream bathing, and forest exploration.', 'Krông Năng, Đắk Lắk', NULL, 'west', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_15.jpg', 0, NULL, 3.0, 'low', 5.0, 12.969100, 108.337100, 1, 'pannellum', NULL, '', '2026-07-16 06:06:49', '2026-08-06 11:40:02', NULL, 'outdoor', 3),
(16, 1, 'Núi Đá Voi Mẹ', 'Mother Elephant Rock', 'nui-da-voi-me', 'Tảng đá nguyên khối lớn nhất Việt Nam mang truyền thuyết kỳ bí.', 'Vietnam\'s largest monolithic rock with mysterious legends.', 'Núi Đá Voi Mẹ là một khối đá granite khổng lồ hình dáng như con voi đang nằm. Du khách có thể leo lên đỉnh để ngắm nhìn toàn cảnh hồ Lắk và rừng nguyên sinh.', 'Mother Elephant Rock is a massive granite block shaped like a lying elephant. Tourists can climb to the top to enjoy a panoramic view of Lak Lake and the primary forest.', 'Lắk, Đắk Lắk', NULL, 'west', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_16.jpg', 0, NULL, 1.5, 'free', 4.5, 12.441100, 108.199100, 1, 'pannellum', NULL, '', '2026-07-16 06:06:49', '2026-08-06 11:40:02', NULL, 'mixed', 1),
(17, 5, 'Bảo tàng Thế giới Cà phê', NULL, 'bao-tang-the-gioi-ca-phe', 'Bảo tàng cà phê thế giới đầu tiên tại Việt Nam', NULL, 'Công trình kiến trúc độc đáo lấy cảm hứng từ nhà dài Tây Nguyên, trưng bày hàng nghìn hiện vật về cà phê toàn cầu.', NULL, 'Số 454 Nguyễn Đình Chiểu, TP. Buôn Ma Thuột', NULL, 'west', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_17.jpg', 1, NULL, 2.5, 'medium', 4.5, 12.692300, 108.049500, 0, 'pannellum', NULL, 'cà phê,bảo tàng,văn hoá', '2026-08-06 00:10:48', '2026-08-06 11:40:02', NULL, 'indoor', 0),
(18, 3, 'Nhà đày Buôn Ma Thuột', NULL, 'nha-day-buon-ma-thuot', 'Di tích lịch sử nhà tù nổi tiếng thời Pháp', NULL, 'Hệ thống nhà tù do thực dân Pháp xây dựng năm 1930, hiện là di tích lịch sử quốc gia.', NULL, 'Số 18 Đội Cấn, TP. Buôn Ma Thuột', NULL, 'west', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_18.jpg', 0, NULL, 1.5, 'free', 4.5, 12.680900, 108.046200, 0, 'pannellum', NULL, 'lịch sử,di tích', '2026-08-06 00:10:48', '2026-08-06 11:40:02', NULL, 'indoor', 0),
(19, 3, 'Bảo tàng Đắk Lắk', NULL, 'bao-tang-dak-lak', 'Bảo tàng văn hoá các dân tộc Tây Nguyên', NULL, 'Trưng bày hiện vật, nhà dài, chiêng và văn hoá của 44 dân tộc anh em.', NULL, 'Số 01 Y Ngông, TP. Buôn Ma Thuột', NULL, 'west', NULL, NULL, NULL, NULL, NULL, NULL, '/assets/images/uploads/dest_19.jpg', 1, NULL, 1.5, 'free', 4.5, 12.687700, 108.042000, 0, 'pannellum', NULL, 'văn hoá,bảo tàng,Ê Đê', '2026-08-06 00:10:48', '2026-08-06 11:40:02', NULL, 'indoor', 0),
