(339, 32, 6, NULL, NULL, 1, 'Sáng', 'Khám phá văn hóa cà phê Buôn Ma Thuột. Thăm quan Bảo tàng Cà phê và thưởng thức hương vị cà phê đặc trưng.', NULL, NULL, NULL, NULL, NULL, 0, 'TP. Buôn Ma Thuột, Đắk Lắk', 'Thuê xe máy (150.000đ/ngày) hoặc taxi để di chuyển giữa các quán cà phê.', 0),
(340, 32, NULL, NULL, NULL, 1, 'Trưa', 'Ăn trưa đặc sản Buôn Ma Thuột và nghỉ ngơi.', NULL, NULL, NULL, NULL, NULL, 0, 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc taxi.', 1),
(341, 32, 2, NULL, NULL, 1, 'Chiều', 'Trekking và khám phá Thác Dray Nur, một trong những thác nước hùng vĩ nhất Tây Nguyên. Chụp ảnh phong cảnh và trải nghiệm không khí trong lành.', NULL, NULL, NULL, NULL, NULL, 0, 'Huyện Krông Ana, Đắk Lắk', 'Xe máy hoặc ô tô thuê từ Buôn Ma Thuột (khoảng 30km).', 2),
(342, 32, NULL, NULL, NULL, 1, 'Tối', 'Ăn tối và trải nghiệm ẩm thực địa phương tại Buôn Ma Thuột. Tự do dạo phố hoặc nghỉ ngơi.', NULL, NULL, NULL, NULL, NULL, 0, 'TP. Buôn Ma Thuột, Đắk Lắk', 'Di chuyển bằng xe máy hoặc đi bộ.', 3),
(343, 32, 4, NULL, NULL, 2, 'Sáng', 'Tham quan Buôn Đôn, tìm hiểu văn hóa săn bắt và thuần dưỡng voi của người Ê Đê và M\'nông. Trải nghiệm cầu treo Buôn Đôn.', NULL, NULL, NULL, NULL, NULL, 0, 'Huyện Buôn Đôn, Đắk Lắk', 'Xe máy hoặc ô tô thuê từ Buôn Ma Thuột (khoảng 40km).', 4),
(344, 32, NULL, NULL, NULL, 2, 'Trưa', 'Ăn trưa tại Buôn Đôn với các món ăn đặc sản rừng núi và nghỉ ngơi.', NULL, NULL, NULL, NULL, NULL, 0, 'Huyện Buôn Đôn, Đắk Lắk', 'Di chuyển bộ hoặc xe máy.', 5),
(345, 32, 1, NULL, NULL, 2, 'Chiều', 'Khám phá Hồ Lắk, hồ nước ngọt tự nhiên lớn thứ hai Việt Nam. Trải nghiệm thuyền độc mộc trên hồ, tìm hiểu văn hóa M\'nông và chụp ảnh hoàng hôn.', NULL, NULL, NULL, NULL, NULL, 0, 'Huyện Lắk, Đắk Lắk', 'Xe máy hoặc ô tô thuê từ Buôn Đôn (khoảng 60km, đi theo đường ven hồ để ngắm cảnh).', 6),
(346, 32, NULL, NULL, NULL, 2, 'Tối', 'Ăn tối tại Hồ Lắk, thưởng thức các món ăn địa phương và nghỉ ngơi tại homestay ven hồ.', NULL, NULL, NULL, NULL, NULL, 0, 'Huyện Lắk, Đắk Lắk', 'Đi bộ hoặc xe máy trong khu vực Hồ Lắk.', 7),
(347, 32, 16, NULL, NULL, 3, 'Sáng', 'Chinh phục Núi Đá Voi Mẹ, tảng đá nguyên khối lớn nhất Việt Nam. Trải nghiệm leo núi và chụp ảnh toàn cảnh khu vực Hồ Lắk.', NULL, NULL, NULL, NULL, NULL, 0, 'Lắk, Đắk Lắk', 'Xe máy từ Hồ Lắk (khoảng 10km).', 8),
(348, 32, NULL, NULL, NULL, 3, 'Trưa', 'Ăn trưa tại khu vực Lắk hoặc trên đường di chuyển đến Krông Năng. Nghỉ ngơi.', NULL, NULL, NULL, NULL, NULL, 0, 'Khu vực Lắk', 'Xe máy.', 9),
(349, 32, 15, NULL, NULL, 3, 'Chiều', 'Thăm quan Thác Thủy Tiên, tuyệt tác thiên nhiên ba tầng giữa chốn đại ngàn Krông Năng. Tắm mát và chụp ảnh phong cảnh.', NULL, NULL, NULL, NULL, NULL, 0, 'Krông Năng, Đắk Lắk', 'Xe máy từ Lắk đến Krông Năng (khoảng 70km).', 10),
(350, 32, NULL, NULL, NULL, 3, 'Tối', 'Quay về Buôn Ma Thuột, ăn tối và nghỉ ngơi tại trung tâm thành phố.', NULL, NULL, NULL, NULL, NULL, 0, 'TP. Buôn Ma Thuột, Đắk Lắk', 'Xe máy hoặc ô tô từ Krông Năng về Buôn Ma Thuột (khoảng 60km).', 11),
(351, 32, 7, NULL, NULL, 4, 'Sáng', 'Tham quan Buôn Akô Dhông, buôn làng Ê Đê đẹp nhất Buôn Ma Thuột. Tìm hiểu kiến trúc nhà dài truyền thống và văn hóa sinh hoạt của người Ê Đê. Chụp ảnh lưu niệm.', NULL, NULL, NULL, NULL, NULL, 0, 'TP. Buôn Ma Thuột, Đắk Lắk', 'Xe máy hoặc taxi từ trung tâm thành phố.', 12),
